type IconName = keyof typeof Icons;

export type CustomIconsProps = {
  name: IconName;
  size?: number;
} & SvgProps;

export const CustomIcon = ({ name, size, ...props }: CustomIconsProps) => {
  const Icon = Icons[name];
  return <Icon width={size} height={size} {...props} />;
};
